mapper.select:
SELECT item_date AS itemDate, cashier_name AS cashierName, item_type AS itemType, NVL(item_value, 0) AS itemValue FROM TR_CASH_SETTLE_DTL WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND item_type = #{itemType}
ORDER BY item_date, cashier_name

SELECT chart_title AS chartTitle, chart_subtitle AS chartSubtitle, date_range AS dateRange, category, NVL(data_value, 0) AS dataValue FROM TR_CASH_SETTLE_CHT WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND chart_title = #{chartTitle}
ORDER BY category
